function validDay(d){return typeof d==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(d)}
function gradeState(grade,owner=profile){let s=owner.grades[grade];if(!s||typeof s!=='object'||Array.isArray(s))s=owner.grades[grade]={facts:{}};if(!s.facts||typeof s.facts!=='object'||Array.isArray(s.facts))s.facts={};return s}
