function queue(grade,owner=profile){const s=gradeState(grade,owner),day=today(),eligible=bank(grade).filter(q=>{const f=fact(s,q.id);return f.cleared!==day&&(!f.due||f.due<=day)}).map(q=>q.id),allow=new Set(eligible);if(!s.queue||s.queue.day!==day||!Array.isArray(s.queue.active)||!Array.isArray(s.queue.review))s.queue={day,active:[],review:[],pool:eligible};else{if(!Array.isArray(s.queue.pool))s.queue.pool=[];const seen=new Set();for(const key of ['active','review','pool'])s.queue[key]=s.queue[key].filter(id=>allow.has(id)&&!seen.has(id)&&(seen.add(id),true));if(s.queue.active.length>roundSize)s.queue.pool.unshift(...s.queue.active.splice(roundSize));for(const id of eligible)if(!seen.has(id))s.queue.pool.push(id)}return s}
function fillRound(s){const q=s.queue;if(q.active.length)return;if(q.review.length){q.active=q.review.splice(0,roundSize);return}while(q.active.length<roundSize&&q.pool.length){const unknown=q.pool.filter(id=>fact(s,id).level===0),review=q.pool.filter(id=>fact(s,id).level>0);const preferred=unknown.length&&review.length?(Number(random())<.75?unknown:review):unknown.length?unknown:review;const id=preferred[sample(preferred.length)];q.pool.splice(q.pool.indexOf(id),1);q.active.push(id)}}
function remaining(s){return s.queue.active.length+s.queue.review.length+s.queue.pool.length}
function success(s,id){const f=fact(s,id),day=today();if(f.cleared===day)return false;f.cleared=day;if(!f.successDays.includes(day)){f.successDays.push(day);f.level=Math.min(4,f.level+1)}f.due=plus(day,intervals[Math.max(0,f.level-1)]);s.queue.active=s.queue.active.filter(v=>v!==id);s.queue.review=s.queue.review.filter(v=>v!==id);return true}
function stats(){const grade=profile.grade,s=queue(grade),day=today(),out={grade,total:bank(grade).length,remaining:remaining(s),workingRemaining:s.queue.active.length+s.queue.review.length,clearedToday:0,due:0,reviewDue:0,new:0,mastered:0,confirmed:0,byOperation:{}};for(const q of bank(grade)){const f=fact(s,q.id),due=f.cleared!==day&&(!f.due||f.due<=day),op=out.byOperation[q.op]||(out.byOperation[q.op]={total:0,remaining:0,clearedToday:0,due:0,reviewDue:0,new:0,mastered:0,confirmed:0});op.total++;if(f.cleared===day){out.clearedToday++;op.clearedToday++}if(due){out.due++;op.due++;op.remaining++;if(f.level>0){out.reviewDue++;op.reviewDue++}if(f.attempts===0){out.new++;op.new++}}if(f.level>=3){out.mastered++;op.mastered++}else if(f.level===2){out.confirmed++;op.confirmed++}}return out}
function choices(answer){const values=[answer];for(const n of [answer+1,answer-1,answer+2,answer-2,answer+3])if(n>=0&&!values.includes(n)&&values.length<4)values.push(n);for(let i=values.length-1;i>0;i--){const j=sample(i+1);[values[i],values[j]]=[values[j],values[i]]}return values}
function begin(options={}){const demo=!!options.demo,grade=profile.grade,owner=demo?clone(profile):profile,runId=++serial,reserved=new Map(),recorded=new Set();if(demo)owner.grades[grade]={facts:{}};let nextAttempt=0;if(!demo)currentRun=runId;const run={limitMs,demo,grade,next(){if(!demo&&(currentRun!==runId||profile.grade!==grade))return null;const s=queue(grade,owner);fillRound(s);const available=s.queue.active.filter(id=>![...reserved.values()].some(q=>q.id===id));if(!available.length)return null;const id=available[sample(available.length)],q=bank(grade).find(q=>q.id===id),token=runId+':'+(++nextAttempt),issued={...q,choices:choices(q.answer),issuedAt:Number(clock()),attemptId:token,token};if((q.op==='add'||q.op==='mul')&&Number(random())<.5){const parts=q.id.split(':');issued.text=parts[2]+' '+(q.op==='add'?'+':'×')+' '+parts[1]}reserved.set(token,issued);if(!demo)save();return clone(issued)},record(question,correct,ms,opts={}){const token=question&&(question.attemptId||question.token),original=reserved.get(token);if(!original||recorded.has(token)||(!demo&&(currentRun!==runId||profile.grade!==grade)))return{accepted:false,reason:'stale-or-duplicate'};if(question.id!==original.id)return{accepted:false,reason:'invalid-question'};recorded.add(token);reserved.delete(token);const s=queue(grade,owner),f=fact(s,original.id),elapsed=Number(ms),fluent=correct===true&&Number.isFinite(elapsed)&&elapsed>=0&&elapsed<=limitMs&&!opts.timeout&&!opts.assisted;f.attempts++;let cleared=false;if(fluent)cleared=success(s,original.id);else{s.queue.active=s.queue.active.filter(id=>id!==original.id);if(!s.queue.review.includes(original.id))s.queue.review.push(original.id);f.level=0;f.due=today()}if(!demo)save();const updated=fact(s,original.id);return{accepted:true,correct:correct===true,fluent,cleared,needsPractice:!fluent,demo,id:original.id,reason:fluent?'cleared':opts.timeout?'timeout':opts.assisted?'assisted':correct===true?'slow':'incorrect',stage:fluent?(updated.level>=3?'mastered':updated.level===2?'confirmed':'cleared-today'):'practice',summary:{remaining:remaining(s),workingRemaining:s.queue.active.length+s.queue.review.length,clearedToday:bank(grade).filter(q=>fact(s,q.id).cleared===today()).length}}}};return run}
function getGrade(){return profile.grade}function setGrade(grade){if(!Number.isInteger(grade)||grade<1||grade>8)throw new RangeError('Grade must be 1 through 8');if(profile.grade!==grade){profile.grade=grade;currentRun=null}queue(grade);save();return stats()}
